
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_pkzb_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_pkzb", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.327422903037303e+00, -4.244096804924306e+00, -4.127445069827013e+00, -3.966084418409348e+00, -3.746708835598360e+00, -3.455830036887953e+00, -3.083874414131409e+00, -2.632658275237150e+00, -2.125187709340381e+00, -1.602656925003649e+00, -1.068790000723984e+00, -7.125092152624987e-01, -5.987235889993638e-01, -4.972112517466503e-01, -3.665798708820461e-01, -2.459964449593941e-01, -1.421157073252051e-01, -5.036873413627341e-02, -1.082144968407094e-02, -1.216216049501113e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


